package net.muxigame.musiccompat.qa.entry042;
import java.net.URI;import java.util.*;import java.util.concurrent.*;import java.security.MessageDigest;import java.nio.charset.StandardCharsets;
/** Bounded QA-only state observations. Never records credentials, signed URIs or exception messages. */
public final class Entry042PlaybackDiagnostics {
 private static final ArrayDeque<Map<String,Object>> events=new ArrayDeque<>();private static final LinkedHashMap<Long,Map<String,Object>> lyrics=new LinkedHashMap<>();private static long lyricId,accountStarted,accountReturned;private static final Map<String,long[]> accountPaths=new LinkedHashMap<>();
 public static synchronized void event(String kind,Map<String,Object> facts){var row=new LinkedHashMap<String,Object>();row.put("kind",kind);row.put("atUtcMillis",System.currentTimeMillis());row.putAll(facts);if(events.size()>=180)events.removeFirst();events.addLast(Collections.unmodifiableMap(row));}
 public static String media(String reference){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(reference.getBytes(StandardCharsets.UTF_8))).substring(0,16);}catch(Exception impossible){throw new IllegalStateException();}}
 public static synchronized void account(boolean returned,boolean cache){String path=StackWalker.getInstance().walk(frames->frames.filter(f->f.getClassName().equals("net.muxigame.musiccompat.burn.PrivatePlayback")&&(f.getMethodName().equals("fetch")||f.getMethodName().equals("lyricOrigin"))).map(f->f.getMethodName().equals("fetch")?"media":"lyrics").findFirst().orElse("other"));var counts=accountPaths.computeIfAbsent(path,k->new long[2]);if(returned){accountReturned++;counts[1]++;}else{accountStarted++;counts[0]++;}event(returned?"private-account-return":"private-account-start",Map.of("path",path,"sameConnectionFreshCache",cache,"started",counts[0],"returned",counts[1]));}
 public static void lyric(URI reference,CompletableFuture<?> future){final long id;synchronized(Entry042PlaybackDiagnostics.class){id=++lyricId;var row=new LinkedHashMap<String,Object>();row.put("id",id);row.put("media",media(reference.toString()));row.put("startedAtUtcMillis",System.currentTimeMillis());row.put("status","pending");if(lyrics.size()>=180){var oldest=lyrics.keySet().iterator();oldest.next();oldest.remove();}lyrics.put(id,row);event("private-lyrics-future-created",Map.of("id",id,"media",media(reference.toString())));}
  future.whenComplete((value,error)->{synchronized(Entry042PlaybackDiagnostics.class){var row=lyrics.get(id);if(row==null)return;String status=future.isCancelled()?"cancelled":error!=null?"exceptional":value==null?"completed-empty":"completed-lyrics";row.put("status",status);row.put("completedAtUtcMillis",System.currentTimeMillis());event("private-lyrics-future-finished",Map.of("id",id,"status",status));}});
 }
 public static synchronized Map<String,Object> snapshot(){var copied=new ArrayList<Map<String,Object>>();for(var row:lyrics.values())copied.add(new LinkedHashMap<>(row));var paths=new LinkedHashMap<String,Object>();for(var e:accountPaths.entrySet())paths.put(e.getKey(),Map.of("started",e.getValue()[0],"returned",e.getValue()[1]));return Map.of("accountStarted",accountStarted,"accountReturned",accountReturned,"accountByPath",paths,"lyrics",copied,"events",List.copyOf(events));}
 private Entry042PlaybackDiagnostics(){}
}
